-- =====================================================================
-- Memorepe — Crea los 2 bancos del examen de manejo de Provincia de Buenos Aires
-- Correr COMPLETO una sola vez en el SQL Editor de Supabase.
-- Si un banco ya existe (mismo título), lo saltea: se puede volver a correr sin duplicar.
-- =====================================================================

-- Examen teórico de manejo – Provincia de Buenos Aires (Clase B) (352 preguntas)
do $$
declare
  v_user uuid;
  v_quiz uuid;
  v_q uuid;
begin
  select id into v_user from users where username = 'memorepe';
  if v_user is null then raise exception 'No existe el usuario @memorepe'; end if;
  if exists (select 1 from quizzes where title = 'Examen teórico de manejo – Provincia de Buenos Aires (Clase B)') then raise notice 'Ya existe: Examen teórico de manejo – Provincia de Buenos Aires (Clase B)'; return; end if;
  values (v_user, 'Examen teórico de manejo – Provincia de Buenos Aires (Clase B)', 'Preguntas del cuestionario oficial para el examen teórico de la licencia de conducir en la Provincia de Buenos Aires, con las respuestas correctas.', 'otro', 'conducir', 'es', 'public', 'Provincia de Buenos Aires', 'Licencia de conducir', 'examen-teorico-manejo-provincia-buenos-aires-clase-b')
  returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
  raise notice 'Creado: % con % preguntas', 'Examen teórico de manejo – Provincia de Buenos Aires (Clase B)', 352;
end $$;

-- Señales y situaciones de tránsito – Provincia de Buenos Aires (186 preguntas)
do $$
declare
  v_user uuid;
  v_quiz uuid;
  v_q uuid;
begin
  select id into v_user from users where username = 'memorepe';
  if v_user is null then raise exception 'No existe el usuario @memorepe'; end if;
  if exists (select 1 from quizzes where title = 'Señales y situaciones de tránsito – Provincia de Buenos Aires') then raise notice 'Ya existe: Señales y situaciones de tránsito – Provincia de Buenos Aires'; return; end if;
  values (v_user, 'Señales y situaciones de tránsito – Provincia de Buenos Aires', 'Señales de tránsito, señas y situaciones reales del cuestionario oficial del examen teórico de manejo de la Provincia de Buenos Aires, con imágenes y respuestas correctas.', 'otro', 'conducir', 'es', 'public', 'Provincia de Buenos Aires', 'Señales de tránsito', 'senales-situaciones-transito-provincia-buenos-aires')
  returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
  raise notice 'Creado: % con % preguntas', 'Señales y situaciones de tránsito – Provincia de Buenos Aires', 186;
end $$;
