  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '“Cada usuario de la vía pública es responsable de una parte del tránsito.” ¿Es correcta ésta premisa?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 6, null) returning id into v_q;
