  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, independientemente del tipo de movilidad elegido.', true, 0), (v_q, 'No, los peatones son usuarios de la vía pública y no están obligados.', false, 1), (v_q, 'Sí pero sólo si estamos conduciendo un vehículo.', false, 2);
