  insert into options (question_id, body, is_correct, "order") values (v_q, 'Acomodar correctamente los espejos retrovisores antes de iniciar la marcha. Mientras se circula, además de revisar los espejos retrovisores, utilizar la visión periférica dando vistazos por encima de los hombros cuando sea necesario.', false, 0), (v_q, 'Antes de realizar una maniobra se debe disminuir la velocidad de circulación, colocar la luz de giro y mirar por los espejos realizando un pequeño movimiento corporal hacia adelante para ampliar el ángulo de visión.', false, 1), (v_q, 'Ambas respuestas, A y B, son correctas.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿A qué se llama “Punto Ciego”?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 301, null) returning id into v_q;
