  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'La siguiente acción del conductor es riesgosa porque:', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 29, '/img/preguntas/pba/0031.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Disminuye su capacidad atencional, limita el sentido de la audición, reduce la capacidad de reacción y aumenta el tiempo necesario para responder ante un estímulo.', false, 0), (v_q, 'El conductor debe mantener ambas manos comprometidas en la acción de conducir y al manipularlo, reduciría su capacidad para maniobrar.', false, 1), (v_q, 'Ambas respuestas, la A y la B, son correctas.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Se encuentra prohibida la acción de la persona señalada con el círculo rojo?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 30, '/img/preguntas/pba/0032.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, porque se encuentra en el asiento delantero.', false, 0), (v_q, 'No, porque la prohibición del uso de telefonía celular alcanza sólo al conductor del vehículo.', true, 1), (v_q, 'Sí, su uso se encuentra prohibido para todos los ocupantes del vehículo.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'La presente conducta, ¿es riesgosa al momento de conducir?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 31, '/img/preguntas/pba/0033.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, porque es considerado un factor de distracción.', true, 0), (v_q, 'Únicamente si se circula a altas velocidades.', false, 1), (v_q, 'Al contrario, ayuda a mantener la atención en la conducción.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'La acción que se presenta en la imagen es considerada riesgosa para la conducción de un vehículo.', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 32, '/img/preguntas/pba/0034.webp') returning id into v_q;
