  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Cuáles de las siguientes acciones son consideradas factores de distracción cuando se conduce un vehículo?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 34, '/img/preguntas/pba/0036.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Las opciones A, B y C.', true, 0), (v_q, 'Las opciones A y C.', false, 1), (v_q, 'Las opciones B y C.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Que indica el señalamiento vertical de color azul A – Restricción B - información C – Prevención Que indica el señalamiento vertical con una orla roja A – Restricción B - información C – Prevención Que indica el señalamiento vertical de color amarillo A – Restricción B - información C – Prevención ¿Qué está indicando el agente de tránsito al realizar esta señal a un conductor?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 35, '/img/preguntas/pba/0037.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Que circule con precaución.', false, 0), (v_q, 'Que detenga el vehículo.', true, 1), (v_q, 'Que continúe avanzando.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si al circular por una vía y la persona señalada le indica detenerse, ¿está obligado usted a obedecer?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 36, '/img/preguntas/pba/0038.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, porque al ser personal de obra está autorizado a regular el paso de vehículos en el tramo donde están trabajando.', true, 0), (v_q, 'Sólo si se percibe una situación riesgosa ya que el personal de obra no tiene la autoridad legal para realizar dicha indicación.', false, 1), (v_q, 'No, porque no tiene autoridad ya que la Ley sólo delega dicha función a los agentes de tránsito.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si se encuentra en esta situación y el personal ferroviario le indica que avance, ¿qué debe hacer?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 37, '/img/preguntas/pba/0039.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Avanzar porque el personal ferroviario está autorizado a regular el paso de vehículos.', true, 0), (v_q, 'Detenerme y esperar hasta que la barrera se levante porque el personal ferroviario no tiene la autoridad legal para realizar dicha indicación.', false, 1), (v_q, 'Detenerme y esperar hasta que la barrera se levante, salvo que la indicación sea realizada por un agente de tránsito ya que es la única autoridad competente.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué indican las señales transitorias naranjas ubicadas en la calzada de la presente imagen?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 38, '/img/preguntas/pba/0040.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Refuerzan el significado de las líneas discontinuas del carril porque es una zona peligrosa.', false, 0), (v_q, 'Nada, no son señales de circulación y es ilegal su colocación.', false, 1), (v_q, 'La prohibición de sobrepasar la línea imaginaria que las une.', true, 2);
