  insert into options (question_id, body, is_correct, "order") values (v_q, 'Tengo la obligación de detener la marcha y cuando no haya más vehículos circulando por la arteria que cruza, puedo reiniciarla.', false, 0), (v_q, 'Al tener prioridad, debo atravesarla rápidamente para no obstaculizar la vía.', false, 1), (v_q, 'Efectuar el cruce con máxima precaución.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si al conducir un vehículo se encuentra en una intersección con esta señalización intermitente, ¿qué actitud debe tomar?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 41, '/img/preguntas/pba/0043.webp') returning id into v_q;
