  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Frente a la demarcación central de la calzada señalada, ¿cuál es la conducta a seguir?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 121, '/img/preguntas/pba/0130.webp') returning id into v_q;
