  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué indica esta demarcación amarilla en la calzada?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 122, '/img/preguntas/pba/0131.webp') returning id into v_q;
