  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué significado tiene el color de las luces encendidas que se indican en la imagen?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 151, '/img/preguntas/pba/0161.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Al estar ubicada en la parte posterior del vehículo, el color blanco es para diferenciarla de las luces de freno, posición y giro.', false, 0), (v_q, 'Al ser de color blanco se obtiene mejor visión cuando la maniobra de retroceso se debe realizar de noche o en condiciones de poca visibilidad.', false, 1), (v_q, 'Indica el sentido de circulación. La luz blanca significa que el vehículo circula en sentido contrario al del vehículo rojo que está detrás de él.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'En cuanto a la velocidad frente a esta situación, ¿qué debería considerar un conductor?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 152, '/img/preguntas/pba/0162.webp') returning id into v_q;
