  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, siempre que está disminuida la visibilidad.', true, 0), (v_q, 'No, porque las luces sólo deben utilizarse por la noche.', false, 1), (v_q, 'Sí, pero sólo en rutas.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Al conducir por un largo lapso de tiempo y en esta condición climática…', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 155, '/img/preguntas/pba/0165.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Es menos probable que aparezca la fatiga, ya que aumenta la atención.', false, 0), (v_q, 'Es necesario descansar con más frecuencia, para evitar la fatiga.', true, 1), (v_q, 'No influye en la aparición de fatiga, siempre y cuando se mantenga una velocidad prudente.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Bajo esta condición climática, ¿es recomendable aumentar la distancia de seguridad y reducir la velocidad?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 156, '/img/preguntas/pba/0166.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'No, al reducir la velocidad, mayor es la proporción de agua en el asfalto.', false, 0), (v_q, 'Sí, con lluvia la adherencia es menor.', true, 1), (v_q, 'No. La distancia de seguridad debe ser siempre la misma.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Cuando conduce bajo esta condición climática, ¿a cuánto se debe incrementar la regla de 2 segundos en la distancia de seguridad?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 157, '/img/preguntas/pba/0167.webp') returning id into v_q;
