  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'En estas condiciones, ¿una incorrecta regulación de la altura de las luces bajas puede producir encandilamiento?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 159, '/img/preguntas/pba/0169.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, porque este efecto se produce por cambios bruscos en la intensidad de la luz.', true, 0), (v_q, 'No, porque este efecto se produce sólo por el uso de la luz alta.', false, 1), (v_q, 'No, porque este efecto se produce en rutas con poca iluminación.', false, 2);
